245		if !ok || q != (Quote{Seq: 3, Moment: 30, Price: 20}) {
246			t.Fatalf("补齐后必须保留最初等待的 seq3（时刻30,价格20）: %+v ok=%v", q, ok)
247		}
248		if e.HasGap("A") {
249			t.Fatal("补齐后缺口必须消失")
250		}
251	}
